
.female-section {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.woman-card {
  background: var(--sys-panel);
  border: 1px solid rgba(255, 95, 162, 0.3);
  border-radius: 10px;
  overflow: hidden;
}

.woman-row {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  background: transparent;
  border: none;
  color: var(--sys-text);
  font-family: inherit;
  font-size: 13px;
  cursor: pointer;
  transition: background 0.15s;
  text-align: left;
}

.woman-row:hover {
  background: rgba(255, 45, 120, 0.12);
}

.woman-name {
  font-weight: 700;
  color: var(--sys-pink);
  text-shadow: 0 0 6px rgba(255, 95, 162, 0.5);
  white-space: nowrap;
}

.woman-meta {
  flex: 1;
  color: var(--sys-lilac);
  font-size: 12px;
  white-space: nowrap;
}

.chevron {
  color: var(--sys-lilac);
  transition: transform 0.2s;
  flex-shrink: 0;
}

.chevron.open {
  transform: rotate(180deg);
}

.woman-detail {
  padding: 0 8px 8px;
  border-top: 1px dashed rgba(181, 108, 255, 0.3);
}
