
.quest-row {
  background: var(--sys-panel);
  border: 1px solid rgba(255, 201, 77, 0.3);
  border-left: 3px solid var(--sys-gold);
  border-radius: 10px;
  padding: 8px 10px;
  margin-bottom: 6px;
}

.quest-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 3px;
}

.quest-name {
  font-weight: 700;
  color: var(--sys-gold);
}

.quest-reward {
  color: var(--sys-gold);
  font-weight: 700;
  font-size: 12px;
  white-space: nowrap;
}

.quest-desc {
  color: var(--sys-text-dim);
  font-size: 12px;
  word-break: break-word;
}
