
.env-bar {
  padding: 8px 12px;
  background: linear-gradient(135deg, rgba(255, 95, 162, 0.16), rgba(181, 108, 255, 0.12));
  border-bottom: 1px solid var(--sys-border);
}

.env-loc {
  display: flex;
  align-items: center;
  gap: 6px;
  font-weight: 700;
  font-size: 14px;
  margin-bottom: 6px;
  color: var(--sys-text);
  text-shadow: 0 0 8px rgba(255, 95, 162, 0.5);
}

.env-emoji {
  font-size: 14px;
}

.env-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
}

.env-cell {
  background: var(--sys-panel);
  border: 1px solid rgba(181, 108, 255, 0.25);
  border-radius: 8px;
  padding: 5px 7px;
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}

.env-k {
  color: var(--sys-lilac);
  font-size: 10px;
}

.env-v {
  color: var(--sys-text);
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.env-festival {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 6px;
}

.festival-item {
  background: rgba(255, 201, 77, 0.08);
  border: 1px solid rgba(255, 201, 77, 0.35);
  border-radius: 8px;
  padding: 4px 8px;
}

.festival-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}

.festival-name {
  color: var(--sys-gold);
  font-weight: 700;
  font-size: 12px;
  text-shadow: 0 0 8px rgba(255, 201, 77, 0.5);
}

.festival-date {
  color: var(--sys-text-dim);
  font-size: 10px;
  white-space: nowrap;
}

.festival-desc {
  color: var(--sys-text);
  font-size: 11px;
  line-height: 1.5;
  margin-top: 1px;
}

.festival-off {
  color: var(--sys-green);
  font-size: 10px;
  margin-top: 1px;
}

@media (max-width: 460px) {
  .env-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}
