
.app-header {
  padding: 14px 16px 12px;
  text-align: center;
  background: linear-gradient(135deg, rgba(255, 45, 120, 0.35), rgba(181, 108, 255, 0.3));
  border-bottom: 1px solid var(--sys-border);
}

.app-title {
  font-size: 20px;
  font-weight: 800;
  letter-spacing: 4px;
  color: #fff;
  text-shadow:
    0 0 10px rgba(255, 45, 120, 0.9),
    0 0 24px rgba(181, 108, 255, 0.7);
}

.app-subtitle {
  font-size: 10px;
  letter-spacing: 3px;
  color: var(--sys-lilac);
  margin-top: 3px;
}
