
.status-kv {
  margin-top: 4px;
}

.talent {
  margin-top: 4px;
  border: 1px solid rgba(255, 201, 77, 0.35);
  border-radius: 10px;
  background: rgba(255, 201, 77, 0.05);
  overflow: hidden;
}

.talent-head {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 10px;
  background: transparent;
  border: none;
  color: var(--sys-gold);
  font-family: inherit;
  font-weight: 700;
  font-size: 12px;
  letter-spacing: 1px;
  cursor: pointer;
  text-align: left;
}

.talent-title {
  flex: 1;
  white-space: nowrap;
}

.talent-count {
  background: var(--sys-gold);
  color: #5a3b00;
  font-size: 11px;
  padding: 0 8px;
  border-radius: 999px;
}

.chevron {
  color: var(--sys-gold);
  transition: transform 0.2s;
  flex-shrink: 0;
}

.chevron.open {
  transform: rotate(180deg);
}

.talent-body {
  padding: 4px 10px 6px;
  border-top: 1px dashed rgba(255, 201, 77, 0.3);
}

.talent-item {
  padding: 3px 0;
  border-bottom: 1px solid rgba(255, 201, 77, 0.15);
}

.talent-item:last-child {
  border-bottom: none;
}

.talent-name {
  font-weight: 700;
  color: var(--sys-gold);
  font-size: 12px;
}

.talent-desc {
  color: var(--sys-text-dim);
  font-size: 11px;
  line-height: 1.6;
  margin-top: 1px;
}
